<?php
putenv('SRMS_DB_NAME=eddt_srms_test');require dirname(__DIR__).'/app/bootstrap.php';
use Srms\Database as DB;use Srms\Finance;use Srms\Registry;
if(PHP_SAPI!=='cli')exit(1);
if(($argv[1]??'')==='worker'){$_SESSION=['user_id'=>$argv[2],'session_version'=>1];Finance::payment(['account_id'=>$argv[3],'amount'=>$argv[4],'request_key'=>$argv[5],'payment_date'=>today(),'payment_method'=>'cash']);exit;}
$tag=substr(uuid(),0,8);$user=Srms\Users::create(['full_name'=>'Concurrency '.$tag,'phone_number'=>'+23326'.random_int(1000000,9999999),'role_id'=>'00000000-0000-0000-0000-000000000001','password'=>bin2hex(random_bytes(12))],true);$_SESSION=['user_id'=>$user,'session_version'=>1];$property=Registry::save('properties',['property_number'=>'CONCURRENT-'.$tag]);$account=Registry::save('accounts',['account_number'=>'CONCURRENT-'.$tag,'property_id'=>$property,'opened_on'=>today()]);$assessment=Finance::assessment(['property_id'=>$property,'assessment_year'=>2026,'annual_amount'=>'100']);Finance::approve($assessment);$bill=Finance::issue($assessment,'2026-12-31');
function workers(string $user,string $account,string $amount,array $keys): void {$jobs=[];foreach($keys as $key){$proc=proc_open([PHP_BINARY,__FILE__,'worker',$user,$account,$amount,$key],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fclose($pipes[0]);$jobs[]=[$proc,$pipes];}foreach($jobs as [$proc,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($proc)!==0)throw new RuntimeException($out.$err);}}
try{workers($user,$account,'75',[uuid(),uuid()]);if(DB::scalar('SELECT credit_amount FROM accounts WHERE id=?',[$account])!=='50.0000')throw new RuntimeException('Concurrent credit mismatch.');echo "PASS Concurrent payments allocate once under account lock\n";$key=uuid();workers($user,$account,'20',[$key,$key]);if(DB::scalar('SELECT credit_amount FROM accounts WHERE id=?',[$account])!=='70.0000'||DB::scalar('SELECT COUNT(*) FROM payments WHERE account_id=?',[$account])!=3)throw new RuntimeException('Duplicate race mismatch.');echo "PASS Concurrent duplicate submissions create one payment\n";}finally{DB::transaction(function()use($account,$bill,$assessment,$property,$user){DB::query('DELETE FROM payment_allocations WHERE bill_id=?',[$bill]);DB::query('DELETE FROM payments WHERE account_id=?',[$account]);DB::query('DELETE FROM ground_rent_bills WHERE id=?',[$bill]);DB::query('DELETE FROM ground_rent_assessments WHERE id=?',[$assessment]);DB::query('DELETE FROM accounts WHERE id=?',[$account]);DB::query('DELETE FROM properties WHERE id=?',[$property]);DB::query('DELETE FROM audit_logs WHERE user_id=? OR (entity_type=? AND entity_id=?)',[$user,'users',$user]);DB::query('DELETE FROM phone_identities WHERE holder_type=? AND holder_id=?',['user',$user]);DB::query('DELETE FROM user_phone_numbers WHERE user_id=?',[$user]);DB::query('DELETE FROM users WHERE id=?',[$user]);});}
